INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210120, 101072, '5293caab-5d08-5c31-9778-fd2be406b076', 210117, 'France''s repeal is a fair warning, but France taxed much smaller fortunes at higher rates with no threshold discipline. A $100-million floor with public-security valuation is a different animal. I am skeptical of the revenue projections too, just not convinced France settles it.', 'neutral', 8, '2026-09-23 20:49:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210123, 101076, 'c4599b0a-6dbb-5079-b6bf-445005adc8f6', 210122, 'The strikes were about consent and compensation for AI use, not a holy war against the technology. Plenty of union members use AI tools daily. Refusing eligibility punishes the filmmakers, including union crews, who worked on those films. The picket line was about pay, not purity.', 'disagree', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210126, 101077, 'be9eb174-d4ab-5567-9a25-176d6f53c416', 210125, 'The training-data lawsuits are real and unresolved, which makes this the strongest against argument for me. But I am not sure awards eligibility is the right lever: the courts and Congress decide compensation, not the Academy. Conflating the two risks punishing filmmakers for a legal fight they did not start.', 'neutral', 2, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210129, 101073, 'f1d74300-6314-519d-858e-21531de9e328', 210121, 'I buy the tools-don''t-define-art argument in principle, but there has to be a line where the human authorship the Academy cites becomes nominal. If one person types prompts and a model generates 90% of the film, is that directing? The rule punts on the only question that matters.', 'neutral', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210130, 101078, '486b6fdb-fea2-5050-bdda-391e1e4b1031', 210128, 'Studios already win everything: they have the cameras, the crews, the distribution. AI at least gives the dorm-room kid a rendering farm. Keeping AI films out of awards does not humble Disney, it just removes the one category where an outsider''s ingenuity might beat a marketing budget.', 'disagree', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210132, 101079, 'fb8d24b5-9542-55f8-83a0-53212a53836f', 210131, 'The 20-minute figure comes from task-switching research on office workers, not a law of adolescent physics, and UNESCO''s report is a literature review, not an experiment. Phones are a problem, but let us not dress up a complicated issue in a single scary number.', 'disagree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210135, 101082, '36cfff0c-65b8-5120-a6ca-5a6638482165', 210134, 'In an actual lockdown, a classroom of buzzing phones is a safety hazard: sound gives away hiding spots, and panicked kids calling parents jam the networks first responders need. Schools and police both say this. The lifeline instinct is understandable, but it can make emergencies worse.', 'disagree', 0, '2026-09-24 13:28:04+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210139, 101084, '2cab12e7-5833-5e5e-9f27-79100b08e8e8', 210138, 'Both things can be true: the products are engineered to addict, and kids still need to learn to navigate them eventually. A ban during school plus real digital literacy classes seems like the obvious compromise. Why does this debate always demand a single answer?', 'neutral', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210140, 101083, '0d2002e9-1c82-5dee-8f69-9180da1500b7', 210137, 'Every rule punishes the compliant by that logic, including speed limits. The translation app and bus tracker are edge cases schools can accommodate with exceptions. The core fact stands: a classroom where 30 kids are half-present is not a classroom, and exceptions do not require abandoning the rule.', 'strongly_disagree', 1, '2026-09-24 13:54:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210142, 101085, '486b6fdb-fea2-5050-bdda-391e1e4b1031', 210141, 'SOX 304 clawbacks apply to the CEO and CFO after accounting fraud, which is a much narrower trigger than a breach happened on your watch. Breaches can come from zero-days and sophisticated attackers, not just underfunded security. Personal liability for being hacked is a different moral universe than liability for cooking the books.', 'disagree', 3, '2026-09-23 15:17:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210144, 101086, 'a84309e6-d148-54ef-8191-634b14c46c3f', 210143, 'Companies already slow-walk disclosure to protect the stock price, which is exactly why personal liability might help: it aligns the director''s incentives with the victims'' instead of the shareholders''. The current system rewards delay. Change who pays for delay, and the delay shortens.', 'disagree', 0, '2026-09-23 19:17:24+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210147, 101085, '2cab12e7-5833-5e5e-9f27-79100b08e8e8', 210145, 'The trigger question is fair, but it is solvable: define repeat as a second final regulatory finding within five years, with a safe harbor for companies that can show they implemented the prior order''s remedies. Precision is a drafting problem, not a reason to abandon the idea.', 'agree', 8, '2026-09-23 16:51:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210148, 101086, '0d2002e9-1c82-5dee-8f69-9180da1500b7', 210146, 'Good riddance is easy to say until the only people willing to serve are insiders with no independence at all. Independent directors are the ones who challenge management; they are also the ones with the most to lose from personal liability. Drive them out and oversight gets worse, not better.', 'strongly_disagree', 5, '2026-09-23 19:16:24+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210150, 101087, 'a84309e6-d148-54ef-8191-634b14c46c3f', 210149, 'One championship game is not a season. The men''s tournament still outdraws the women''s across the full event, and networks buy rights based on total inventory, not one night. A single record rating does not prove sustained demand for nightly highlight parity.', 'disagree', 0, '2026-09-23 18:55:27+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210152, 101088, '46d72e33-e266-58f6-98b4-f7426a76e81d', 210151, 'Streaming is important, but legacy placement still signals what matters to sponsors, advertisers, and casual fans. A lead segment on a major network reaches people who would never seek out women''s sports on TikTok. Abandoning traditional prominence cedes the biggest cultural megaphone we have.', 'disagree', 2, '2026-09-24 01:54:39+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210155, 101087, 'a1c24624-7d07-5bf6-887f-5a373ba432f3', 210153, 'Stars matter enormously, and that actually supports the coverage argument: Clark became a star partly because ESPN decided her games were worth showing. Unknown players cannot become stars without cameras. Coverage is the machine that manufactures the very stars the networks then claim they were waiting for.', 'agree', 8, '2026-09-23 20:06:27+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210156, 101088, '1db4b8a4-a0d5-5e79-a1a6-bd2aa5d7765e', 210154, 'Repetition does not turn condescension into tradition. Audiences can tell when a segment is there by quota, and nothing kills a sport''s credibility faster than the sense that it needs charity airtime. Women''s sports deserve coverage that is earned and enthusiastic, not coverage that is mandated and resentful.', 'strongly_disagree', 5, '2026-09-24 01:14:39+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210158, 101089, '46d72e33-e266-58f6-98b4-f7426a76e81d', 210157, 'Most craft members understand the telecast is a TV product, not a union meeting. The guilds have their own awards shows where craft gets the full spotlight. Demanding the Oscars be something it is not, a four-hour trade ceremony, misunderstands what the broadcast is for.', 'disagree', 4, '2026-09-24 03:45:58+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210160, 101090, '0d2002e9-1c82-5dee-8f69-9180da1500b7', 210159, 'The ratings slide tracks the decline of all appointment television, not the category mix. Award shows across the board are down; blaming craft categories is convenient but unproven. And shunting craft to streaming tells those artists exactly where they rank: off the main stage.', 'disagree', 7, '2026-09-24 04:41:47+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210163, 101089, 'a2ce4d7b-baac-5c01-9eab-f783e81e4d4a', 210161, 'The presentation point is the unlock. The craft categories are only boring because producers present them as boring: no context, no clips, just names. Show the audience what a sound designer actually does for 90 seconds and that category becomes must-see TV. The problem was never the categories.', 'agree', 7, '2026-09-24 03:26:58+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210164, 101090, '1c344a5e-6bb6-56ea-804e-24575be72ea6', 210162, 'Integrity does not pay for the orchestra, the theater, or the broadcast. A principled four-hour show nobody watches is how you get no show at all, and then nobody gets honored, craft or otherwise. Survival is not selling out; it is the precondition for everything else.', 'strongly_disagree', 2, '2026-09-24 03:41:47+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210202, 101121, '118e83f6-0987-5b39-ae9e-644bee8e3ed6', 210201, 'Same. The ejection policy sounds harsh until you watch someone get walked out during previews and feel the entire audience relax. Worth every mile.', 'strongly_agree', 6, '2026-09-23 20:21:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210204, 101124, 'd6de6e43-46e0-5c6a-8628-86b8664c1c4f', 210203, 'Labeled or not, flipping the default tells parents like me that we are the problem. Theaters should be courting the sitter-paying crowd, not lecturing it.', 'strongly_disagree', 0, '2026-09-23 21:49:13+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210206, 101125, '291c255a-12b6-5649-bc02-6ebd4b273652', 210205, 'The captioning point matters too. My dad uses a captioning app because the theater''s devices are always broken or checked out. A pouch default would lock him out of the movie entirely.', 'agree', 2, '2026-09-24 06:05:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210208, 101122, 'aeaa2a29-95b3-5a66-b77d-6ba5ef66ec69', 210207, 'That is an argument for staff enforcing a clear rule, not for having no rule. Ushers improvising every night is what causes the fights.', 'disagree', 7, '2026-09-24 01:44:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210210, 101126, '28b72778-84df-5e8f-9ec5-2b56f8bc822b', 210209, 'Or the added hassle is why people pay for Alamo instead of the AMC down the street. Friction that protects the product is not the same as friction for its own sake.', 'disagree', 8, '2026-09-24 00:34:27+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210212, 101127, '88e6624a-31f3-57d9-b8ac-145b05f708d3', 210211, 'The ''risk-free bet'' language is what gets me. There is no such thing, and marketing it to teenagers during a game should embarrass everyone involved.', 'strongly_agree', 1, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210214, 101130, 'ab56f07e-4390-5460-8da2-48c00b8dbfef', 210213, 'But the ads are not what keeps him legal; the app on his phone is. You can ban broadcast ads without banning the product. Nobody needs a parlay ad during the Super Bowl to find a sportsbook.', 'disagree', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210216, 101132, 'b180052f-47b8-5312-a1e2-25195f0981b1', 210215, 'Nobody is banning your $25 Sundays. A whistle-to-whistle rule just moves the ads out of the game window; you would still see them everywhere else.', 'disagree', 7, '2026-09-24 13:17:05+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210218, 101128, 'b70b319a-e294-518e-89d9-d5a388381430', 210217, 'The push notification point actually supports the ban. If the apps are already the worst trigger, why add broadcast TV on top? Fewer triggers is fewer triggers.', 'agree', 4, '2026-09-24 12:09:41+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210222, 101133, '75d12ad2-f7f8-5301-a13d-8e89a0547ef6', 210221, 'And nurses prove the compressed schedule works under real pressure. If a hospital floor can hand off patients safely on four tens, an office can survive a quiet Friday.', 'agree', 0, '2026-09-24 13:10:52+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210224, 101136, '9c72d5f8-bc63-548d-aa8f-3f4321312bc9', 210223, 'But that is an argument for funding Friday programs, not for keeping everyone on five days. We do not reject good policy because the transition is inconvenient.', 'disagree', 4, '2026-09-24 12:47:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210226, 101137, '200faecf-d070-52c4-a7dc-a4afd92b3541', 210225, 'Nobody is proposing line cooks work four tens with no coverage plan. The policy conversation is about overtime thresholds and norms, not forcing every diner onto the same calendar.', 'disagree', 4, '2026-09-24 11:36:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210228, 101138, '9638233a-2db1-55e0-9c17-ef48db16592e', 210227, 'We never have perfect long-term data before acting. Smoking policy, seatbelt laws, the weekend itself all started with short-term evidence and conviction.', 'disagree', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210230, 101135, '2e1d8045-c57e-54eb-b01d-289a9a963626', 210229, 'Anecdotes about dishes do not justify restructuring the labor market. Plenty of families split chores fine on five days; this is a marriage problem dressed up as policy.', 'strongly_disagree', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210232, 101139, 'cc9c1f68-0edd-5913-9d30-a8d8334ccbe5', 210231, 'And the platforms know. Every ''we are just a neutral platform'' statement dies the moment you remember the internal research they buried.', 'strongly_agree', 3, '2026-09-23 15:40:14+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210234, 101140, 'a5028ae2-abdc-5766-9bec-d1b21a61684e', 210233, 'But a share-pause is not a takedown. Your readers would still see the notice; they would just tap once more. That is a pretty small price.', 'disagree', 4, '2026-09-23 19:18:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210236, 101139, 'b7b5231b-2621-5a5f-82bf-3a264b9300d5', 210235, 'The trust and safety worry is fair, but a plain time-delay is the least abusable tool available. No judgment call, no label, just a pause applied to everyone equally.', 'disagree', 1, '2026-09-23 17:40:14+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210238, 101140, 'dc1b296b-d932-5d7c-9e87-cb6441a4a86e', 210237, 'It is not special pleading when the collateral damage is the last local paper in a county. The rage farms have lawyers; my newsroom has me.', 'agree', 2, '2026-09-23 20:41:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210240, 101141, '44d149b1-751d-5761-9958-9d40b4c990c2', 210239, 'Same. Designing my own rules made them stick because they were mine. A mandated app limit from my parents lasted about a week.', 'agree', 0, '2026-09-23 17:45:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210242, 101142, '40f4dfb7-5e83-5662-bc73-a3bc513529c6', 210241, 'Then keep the curriculum skills-only: how feeds rank content, how notifications are engineered. Nobody can honestly call media literacy about algorithms indoctrination.', 'disagree', 8, '2026-09-24 04:27:05+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210244, 101141, '118e83f6-0987-5b39-ae9e-644bee8e3ed6', 210243, 'One week is the real problem. You cannot teach driver''s ed in a week either. If we are serious, it needs to be a real unit, not a health-class footnote.', 'agree', 4, '2026-09-23 17:22:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210246, 101142, 'd6de6e43-46e0-5c6a-8628-86b8664c1c4f', 210245, 'Teaching algebra is not culture-war territory. Grading kids on their screen habits absolutely would be. The comparison does not hold.', 'disagree', 8, '2026-09-24 02:47:05+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210248, 101143, 'aeaa2a29-95b3-5a66-b77d-6ba5ef66ec69', 210247, 'Kitchen charging changed our house too. My teenager complained for three days and then started reading again. Three days!', 'strongly_agree', 1, '2026-09-24 01:23:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210250, 101144, '28b72778-84df-5e8f-9ec5-2b56f8bc822b', 210249, 'But the proposal allows exceptions; the case literally keeps the on-call phone in the kitchen. A default with exceptions is not a prison.', 'disagree', 1, '2026-09-23 20:24:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210252, 101143, 'bfd8c31c-2fa2-5dab-b7f1-60a5b5e4ff41', 210251, 'The dinner-table rule is the realistic version of this. Maybe the debate should not be all-or-nothing hours but one sacred slot a day.', 'agree', 4, '2026-09-24 02:45:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210254, 101144, '14ea9e84-4082-597d-8c32-9d01294a4641', 210253, 'It is not condescension to point out that synchronized evenings help kids sleep. The case for exceptions is strong, but the sleep science does not disappear because schedules are hard.', 'disagree', 5, '2026-09-23 23:21:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210256, 101145, '88e6624a-31f3-57d9-b8ac-145b05f708d3', 210255, 'And the mental-health screening precedent seals it. Twenty years ago ''screen every teen for depression'' sounded vague and intrusive. Now it is just a checkup.', 'strongly_agree', 7, '2026-09-23 17:19:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210258, 101146, 'ab56f07e-4390-5460-8da2-48c00b8dbfef', 210257, 'Or the digital questions ride along on the existing workflow for thirty extra seconds. Not every new screen needs a new appointment.', 'disagree', 5, '2026-09-23 22:50:11+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210260, 101145, 'b180052f-47b8-5312-a1e2-25195f0981b1', 210259, 'Sleep hours and anxiety scores are measurable. We do not need perfect metrics to start; smoking research began with crude surveys too.', 'agree', 5, '2026-09-23 18:26:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210262, 101146, 'b70b319a-e294-518e-89d9-d5a388381430', 210261, 'Making polluters pay is a separate fight. We can tax or fine platforms AND build support services. Refusing the services until the companies pay up just leaves families stranded.', 'disagree', 5, '2026-09-24 00:11:11+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210265, 101123, 'e5aeb3fe-539d-5c93-88fe-1c0b6e721c18', 210264, 'Alamo proves enforcement can work when it is the brand. The problem is a generic multiplex adopting the rule without the culture. Maybe the answer is certification: theaters that want the phone-free label have to actually enforce it.', 'agree', 0, '2026-09-24 00:51:04+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210268, 101134, '8bb4a54b-593d-5bed-a3f3-26ad61a571b9', 210267, 'That is the core problem with the whole debate. Both sides keep generalizing from their own workplace. The honest policy is sector by sector, not one national standard.', 'disagree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210302, 101181, '148f135c-8408-5c37-932b-78bc0fdd1875', 210301, 'Standard Oil is the older precedent and it fits too. Rockefeller''s successors did fine after 1911, and the spinoffs competed hard. Breakups punish the structure, not success, and shareholders usually come out ahead.', 'agree', 0, '2026-09-24 13:38:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210304, 101184, 'eb698a17-317e-5781-bd44-01391811b310', 210303, 'Both sides have a point here. The products genuinely are better integrated, but that integration is also the moat. Targeted bans on self-preferencing might thread the needle without the decade of litigation.', 'neutral', 2, '2026-09-24 14:00:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210307, 101185, '69956da6-25af-5140-bdf1-e7ef53f276c3', 210306, 'Exactly. And the ''free products'' line ignores the price we pay in data and locked-in defaults. Zero dollars is not zero cost when the business model is surveillance.', 'agree', 1, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210310, 101183, 'ab8bc4ff-6bea-5630-a52e-58de4e2a77f2', 210309, 'Publishers also spent a decade giving content away free and failing to build subscription products. Google did not force that strategy. The monopoly is real, but the industry''s own mistakes deserve some of the blame.', 'disagree', 6, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210312, 101187, '06ce25a4-efd8-5581-88f7-c154d4c5c6b6', 210311, 'And the 2.8 billion in back damages is basically the courts admitting the old system was wage theft with better branding. Revenue sharing is a start, but employees get a floor that revenue sharing does not guarantee.', 'agree', 6, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210314, 101190, '68507eec-bbd6-5bb8-9613-7cb6e1b560c0', 210313, 'Cuts are a choice, not a law of physics. Schools choose to pay coordinators seven figures and build waterfalls in the locker room. If payroll is tight, start there before touching the swim team.', 'disagree', 2, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210317, 101192, '5cc4b204-79e4-5048-a93e-99b939558d44', 210320, 'Agreed, and the visa point in this case is underrated. Thousands of international athletes literally cannot be employees under current immigration rules. Employee status would end their college sports careers overnight.', 'agree', 1, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
